import cadquery as cq
X,Y,Z=1.0,0.32,0.6
b=cq.Workplane("XY").box(X,Y,Z).translate((X/2,Y/2,Z/2))
# figure-8 pocket on -Y face
for (x,z,r) in [(0.2,0.36,0.13),(0.36,0.33,0.1)]:
    b=b.cut(cq.Workplane("XZ").center(x,z).circle(r).extrude(-0.04))
for (x,z,r,d) in [(0.5,0.25,0.035,0.1),(0.63,0.16,0.035,0.1)]:
    b=b.cut(cq.Workplane("XZ").center(x,z).circle(r).extrude(-d))
# +Y face grooves along Z
for x in (0.45,0.55):
    b=b.cut(cq.Workplane("XY").center(x,Y).circle(0.05).extrude(Z))
for z in (0.3,0.45):
    b=b.cut(cq.Workplane("YZ").workplane(offset=0.4).center(Y,z).circle(0.045).extrude(0.2))
for (x,z) in [(0.2,0.3),(0.8,0.38)]:
    b=b.cut(cq.Workplane("XZ").workplane(offset=-Y).center(x,z).circle(0.035).extrude(0.1))
cq.exporters.export(b,"submission.step")

